# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: Check a GitHub Copilot seat against what the repo's AI needs (ds.ai.model): which
#   models it serves, and whether the ds.ai smash agent answers through one of them. Started as
#   the trial that showed a Copilot seat is enough for Pydantic AI; kept as the seat's check.
# Models: GPT ids are served on Copilot's Responses endpoint, Claude / Gemini ids on chat
#   completions; the model list says which, and `ask` picks accordingly. Default: the repo's
#   model (DEFAULT_AI_MODEL in pkgs/ds/util/const.py).
# Token: GITHUB_COPILOT_API_KEY / COPILOT_GITHUB_TOKEN if set, else the one stored by
#   `ds settings sync`, else `gh auth token`.
#
# Example CLI Commands:
#   1. Is Copilot reachable, which models:   uv run experimental/copilot_agent/copilot_agent.py models
#   2. Ask the smash agent:                  uv run experimental/copilot_agent/copilot_agent.py ask "Little Mac jab 1 damage?"
#   3. Ask with another model:               uv run experimental/copilot_agent/copilot_agent.py ask "hi" --model claude-haiku-4.5
#   4. Plain model, no ds.ai tools:          uv run experimental/copilot_agent/copilot_agent.py ask "hi" --bare
# ---------------------------------------------------------------------------
from __future__ import annotations

import os
import shutil
import subprocess
from typing import Annotated

import httpx
import typer
from ds.ai.model import model_label
from ds.settings import get_settings
from pydantic_ai import Agent
from pydantic_ai.messages import ToolCallPart
from pydantic_ai.models import Model
from pydantic_ai.models.github_copilot import GitHubCopilotModel
from pydantic_ai.models.openai import OpenAIResponsesModel
from pydantic_ai.providers.github_copilot import GitHubCopilotProvider

DEFAULT_MODEL = model_label()  # the repo's model, eg gpt-5.6-luna
TOKEN_ENV_VARS = ("GITHUB_COPILOT_API_KEY", "GITHUB_COPILOT_API_TOKEN", "COPILOT_GITHUB_TOKEN")
# the two Copilot endpoints Pydantic AI can speak, in order of preference
CHAT_ENDPOINT = "/chat/completions"  # GitHubCopilotModel, the built-in provider's own path
RESPONSES_ENDPOINT = "/responses"  # OpenAIResponsesModel pointed at Copilot: the only way to GPT ids

app = typer.Typer(no_args_is_help=True, add_completion=False)


def copilot_token() -> tuple[str, str]:
    """The token to send to Copilot and where it came from: an env var, else the stored one,
    else the gh CLI's login.
    """
    for name in TOKEN_ENV_VARS:
        if os.getenv(name):
            return os.environ[name], f"${name}"
    if stored := get_settings().github_copilot_token:
        return stored.get_secret_value(), "ds settings (keyring)"
    if shutil.which("gh"):
        result = subprocess.run(["gh", "auth", "token"], capture_output=True, text=True, check=False)
        if result.returncode == 0 and result.stdout.strip():
            return result.stdout.strip(), "gh auth token"
    typer.echo("No Copilot token: log in with `gh auth login`, then run `ds settings sync`.", err=True)
    raise typer.Exit(1)


def copilot_provider() -> GitHubCopilotProvider:
    token, source = copilot_token()
    typer.echo(f"token: {source}", err=True)
    return GitHubCopilotProvider(api_key=token)


def catalog(provider: GitHubCopilotProvider) -> list[dict]:
    """Every model this Copilot seat lists (GET /models), sorted by id. Exits when Copilot refuses."""
    client = provider.client
    response = httpx.get(
        f"{str(client.base_url).rstrip('/')}/models",
        # the provider's Copilot client headers (minus the SDK's unset markers) plus the token
        headers={
            **{k: v for k, v in client.default_headers.items() if isinstance(v, str)},
            "Authorization": f"Bearer {client.api_key}",
        },
        timeout=30,
    )
    if response.status_code != httpx.codes.OK:
        typer.echo(f"Copilot refused: HTTP {response.status_code}: {response.text[:300]}", err=True)
        raise typer.Exit(1)
    return sorted(response.json()["data"], key=lambda m: m["id"])


def endpoint_for(model: dict) -> str | None:
    """The endpoint to reach a catalog entry on: chat completions, else Responses, else None."""
    endpoints = model.get("supported_endpoints") or []
    return next((e for e in (CHAT_ENDPOINT, RESPONSES_ENDPOINT) if e in endpoints), None)


def copilot_model(name: str, provider: GitHubCopilotProvider) -> tuple[Model, str]:
    """The Pydantic AI model for a Copilot id, and the endpoint it uses. Exits on an unusable id."""
    entry = next((m for m in catalog(provider) if m["id"] == name), None)
    endpoint = endpoint_for(entry) if entry else None
    if endpoint is None:
        reason = "serves it on no endpoint Pydantic AI speaks" if entry else "doesn't list it"
        typer.echo(f"Can't use {name!r}: this Copilot seat {reason}. See the `models` command.", err=True)
        raise typer.Exit(1)
    if endpoint == CHAT_ENDPOINT:
        return GitHubCopilotModel(name, provider=provider), endpoint
    return OpenAIResponsesModel(name, provider=provider), endpoint


@app.command()
def models(
    all_models: Annotated[bool, typer.Option("--all", help="Also list ids Pydantic AI can't reach.")] = False,
) -> None:
    """List the models this Copilot seat serves (the quickest check that the token works at all)."""
    for model in catalog(copilot_provider()):
        endpoint = endpoint_for(model)
        if endpoint or all_models:
            policy = (model.get("policy") or {}).get("state") or "-"
            typer.echo(
                f"{model['id']:<28} {model.get('vendor', ''):<14} {endpoint or 'unreachable':<18} policy={policy}"
            )


@app.command()
def ask(
    prompt: str,
    model: Annotated[str, typer.Option(help="A Copilot model id, see the `models` command.")] = DEFAULT_MODEL,
    bare: Annotated[bool, typer.Option("--bare", help="A plain agent, without the ds.ai tools.")] = False,
) -> None:
    """Ask the ds.ai smash agent (or a bare one), answered by a Copilot model."""
    run_model, endpoint = copilot_model(model, copilot_provider())
    if bare:
        agent = Agent(name="copilot-bare")
    else:
        from ds.ai import agent  # late: importing ds.ai loads every capability
    result = agent.run_sync(prompt, model=run_model)
    typer.echo(result.output)
    tools = [
        part.tool_name for message in result.all_messages() for part in message.parts if isinstance(part, ToolCallPart)
    ]
    usage = result.usage
    typer.echo(
        f"\n[{model} via github-copilot {endpoint}] requests={usage.requests} in={usage.input_tokens}"
        f" out={usage.output_tokens} tools={tools or 'none'}",
        err=True,
    )


if __name__ == "__main__":
    app()
